CREATE TABLE public.consultation_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), contact_name text NOT NULL, email text NOT NULL, phone text, organisation_type text NOT NULL DEFAULT 'individual' CHECK (organisation_type IN ('individual','school','academy','club')), message text NOT NULL, status text NOT NULL DEFAULT 'new' CHECK (status IN ('new','contacted','closed')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT, UPDATE ON public.consultation_requests TO authenticated; GRANT ALL ON public.consultation_requests TO service_role; ALTER TABLE public.consultation_requests ENABLE ROW LEVEL SECURITY; CREATE POLICY "staff manage consultation requests" ON public.consultation_requests FOR ALL TO authenticated USING (public.is_vito_staff(auth.uid())) WITH CHECK (public.is_vito_staff(auth.uid())); CREATE TRIGGER consultation_requests_updated BEFORE UPDATE ON public.consultation_requests FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();